<?php use App\Domain\Quotes\QuoteRules; ?>
<form method="post" action="/admin/quotes/action" class="quote-action-form"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($quote['id']) ?>"><input type="hidden" name="lock_version" value="<?= e($quote['lock_version']) ?>"><input type="hidden" name="operation_key" value="<?= e($operationKey) ?>"><label class="admin-field"><span>Motivo / justificación</span><input name="reason" maxlength="500" placeholder="Obligatorio para autorizar, rechazar o cancelar"></label><div class="quote-toolbar">
<?php if($version['status']==='draft'&&$actions['issue']&&in_array($quote['status'],['preparing','pending_approval'],true)):?><button class="admin-primary-button" name="action" value="issue">Emitir cotización</button><?php endif?>
<?php if($quote['status']==='pending_approval'&&$actions['approve']):?><button class="admin-secondary-button" name="action" value="approve">Autorizar descuento</button><?php endif?>
<?php if($quote['assigned_user_id']===null&&$actions['assign']):?><button class="admin-secondary-button" name="action" value="assign">Tomar cotización</button><?php endif?>
<?php if(in_array($quote['status'],['sent','rejected','expired'],true)&&$actions['edit']):?><button class="admin-secondary-button" name="action" value="revise">Crear nueva versión</button><?php endif?>
<?php if($quote['status']==='sent'&&$actions['accept']):?><button class="admin-primary-button" name="action" value="accepted" data-confirm="¿Confirmas la aceptación del cliente y el apartado de inventario?">Registrar aceptación y apartar</button><?php endif?>
<?php if($actions['status']):foreach(QuoteRules::TRANSITIONS[$quote['status']]??[]as $to):if($to==='accepted'||($to==='expired'&&$version['valid_until']>=QuoteRules::today()))continue;?><button class="admin-secondary-button" name="action" value="<?= e($to) ?>"><?= e(['cancelled'=>'Cancelar cotización','rejected'=>'Registrar rechazo','expired'=>'Marcar vencida'][$to]??$to) ?></button><?php endforeach;endif?></div></form>